"""Exact unselected crest route/controller request; CARLA execution pending."""
import json
import xml.etree.ElementTree as ET
from pathlib import Path

CAMERAS = ('overview','approach','reference_corner','driver_reference')


def phase_at(config, frame):
    if not 0 <= frame < 600:
        raise ValueError('frame outside 600-frame window')
    hits = [p for p in config['control_phases'] if p['first_frame'] <= frame <= p['last_frame']]
    if len(hits) != 1:
        raise ValueError('uncovered or overlapping controller phase')
    return hits[0]


def check(config, road_text):
    if config['law_id'] != 'NRS-484B-213-2a' or config['cell_id'] != 'C230259' or config['actor'] != 'motor_vehicle_driver':
        raise ValueError('wrong frozen assignment identity')
    suffix = config['case_id'].split('__')[-1]
    if config['case_id'] != config['selected_case_id'] or suffix not in ('probe_a','probe_b','curve_right','curve_left','one_way_crest','one_way_curve'):
        raise ValueError('wrong exact draft case identity')
    if (config['duration_frames'],config['duration_s'],config['rate_hz']) != (600,30,20):
        raise ValueError('short or unsynchronized source window')
    if tuple(c['name'] for c in config['cameras']) != CAMERAS or any(c['fps'] != 20 for c in config['cameras']):
        raise ValueError('four synchronized named cameras required')
    one_way = suffix.startswith('one_way')
    if config['road_directionality'] != ('one_way' if one_way else 'two_way') or config['ego_lane_id'] != ('-2' if one_way else '-1'):
        raise ValueError('wrong road directionality or ego route')
    if not one_way and config['opposing_lane_id'] != '1':
        raise ValueError('two-way opposing-lane route required')
    root = ET.fromstring(road_text)
    lanes = root.findall('.//laneSection/left/lane') + root.findall('.//laneSection/right/lane')
    if sorted(l.get('id') for l in lanes) != (['-1','-2'] if one_way else ['-1','1']):
        raise ValueError('OpenDRIVE lane direction geometry missing')
    elevations = root.findall('.//elevationProfile/elevation')
    curve = suffix.endswith('curve') or suffix.startswith('curve')
    arcs = root.findall('.//planView/geometry/arc')
    if curve:
        if not arcs or not any(abs(float(a.get('curvature',0))) > 0 for a in arcs):
            raise ValueError('curve geometry missing')
    elif len(elevations) < 4 or not any(float(e.get('c',0)) < 0 for e in elevations):
        raise ValueError('crest elevation profile missing')
    if one_way:
        if config['other_vehicle']['route_direction'] != 'same' or config['other_vehicle']['lane_id'] != '-1':
            raise ValueError('one-way same-direction participant required')
    elif config['other_vehicle']['route_direction'] != 'opposing' or config['other_vehicle']['lane_id'] != '1':
        raise ValueError('opposing participant absent')
    if config['hazard_distance_legal_judgment'] is not None or config['physical_verified'] is not False:
        raise ValueError('invented physical or legal result')
    if [phase_at(config,i) for i in range(600)][-1]['last_frame'] != 599:
        raise ValueError('controller incomplete')
    targets = [phase_at(config,i)['target_lane_id'] for i in (0,299,599)]
    if suffix in ('probe_a','curve_right') and targets != ['-1','-1','-1']:
        raise ValueError('right-side probe controller changed')
    expected_left_lane = '-1' if one_way else '1'
    expected_base_lane = '-2' if one_way else '-1'
    if suffix in ('probe_b','curve_left','one_way_crest','one_way_curve') and targets != [expected_base_lane,expected_left_lane,expected_base_lane]:
        raise ValueError('left-side probe controller changed')
    return {'frames':600,'rate_hz':20,'four_cameras':list(CAMERAS),
            'road_directionality':config['road_directionality'],'geometry':'curve' if curve else 'crest',
            'physical_verified':False,'legal_verdict':None}

if __name__ == '__main__':
    import argparse
    p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');args=p.parse_args()
    if not args.check:
        raise SystemExit('unselected diagnostic only; Native capture implementation pending')
    print(json.dumps(check(json.loads(Path('config.json').read_text()),Path('road.xodr').read_text())))

"""Exact source-owned Native entrypoint for the six selected feature cases."""
import argparse
import hashlib
import json
from pathlib import Path

from draft_runner import check as check_geometry


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def check(bundle):
    bundle = Path(bundle)
    config = json.loads((bundle / 'config.json').read_text())
    assignment = json.loads((bundle / 'assignment-source.json').read_text())
    case = config.get('case_id')
    if not isinstance(case, str) or assignment['assignment_id'] + '__' + case.split('__')[-1] != case:
        raise ValueError('Selected case not bound to frozen assignment')
    if config.get('assignment_sha256') != sha(bundle / 'assignment-source.json') or config.get('road_sha256') != sha(bundle / 'road.xodr'):
        raise ValueError('Selected assignment or road source changed')
    if config.get('candidate_id') not in ('primary', 'fallback1'):
        raise ValueError('Unknown selected candidate')
    if config.get('original_native_observed') is not False or config.get('physical_verified') is not False:
        raise ValueError('Unreviewed physical observation claimed')
    geometry = check_geometry(config, (bundle / 'road.xodr').read_text())
    if len(config.get('supported_case_ids', [])) != 1 or config['supported_case_ids'][0] != case:
        raise ValueError('Selected exact case support differs')
    if len(config.get('required_atoms', [])) == 0 or config.get('source_packets') is None:
        raise ValueError('Missing pinned Core atom/source policy')
    return {'case_id': case, 'candidate_id': config['candidate_id'],
            'geometry': geometry, 'frames': 600,
            'native_executed': False, 'legal_verdict': None}


def main():
    p = argparse.ArgumentParser()
    p.add_argument('--check', action='store_true')
    p.add_argument('--bundle', type=Path, default=Path.cwd())
    p.add_argument('--output-dir', type=Path)
    p.add_argument('--host')
    p.add_argument('--port', type=int)
    args = p.parse_args()
    checked = check(args.bundle)
    if args.check:
        print(json.dumps(checked))
        return
    if not args.output_dir or not args.host or not args.port:
        p.error('Native output, host and port required')
    from capture_feature import execute
    execute(args.bundle, args.output_dir, args.host, args.port, checked)


if __name__ == '__main__':
    main()

"""Saved-only source-bound finalizer; no CARLA dependency or legal verdict."""
import argparse
import hashlib
import json
from pathlib import Path

from measure_feature import measure, read_rows

VIDEOS = ('overview.mkv', 'approach.mkv', 'reference_corner.mkv', 'driver_reference.mkv')
SOURCES = ('native-feature-source.jsonl', 'road-context.json', 'video_frames.jsonl',
           'trace.jsonl', 'capture/evidence.jsonl')
CHANNELS = ('st.grade', 'st.curvature', 'st.sight_distance',
            'drv.sight_distance_adequate', 'st.centre_line', 'rel.occupies',
            'drv.approaching', 'st.one_way_roadway', 'rel.oncoming')


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def measure_feature(trace_path, road_path):
    return measure(trace_path, road_path)


def value(name, row, road):
    if name == 'st.grade':
        return {'feature_kind': road['feature_kind'], 'grade_profile_source': road.get('grade_profile_source')}
    if name == 'st.curvature':
        return {'feature_kind': road['feature_kind'], 'curvature_source': road.get('curvature_source')}
    if name == 'st.sight_distance':
        return {'clear_m': row['sight_clear_m'], 'censored': row['sight_censored']}
    if name == 'drv.sight_distance_adequate':
        return {'clear_m': row['sight_clear_m'], 'available_forward_road_m': row['available_forward_road_m'],
                'legal_adequacy_judgment': None}
    if name == 'st.centre_line':
        return {'source': road['centerline_source'], 'ego_s_m': row['ego_s_m']}
    if name == 'rel.occupies':
        return {'body_min_signed_m': row['ego_body_min_signed_m'],
                'body_max_signed_m': row['ego_body_max_signed_m']}
    if name == 'drv.approaching':
        return row['ego_s_m'] < road['feature_start_s_m'] and row['ego_forward_mps'] > 0
    if name == 'st.one_way_roadway':
        return {'authored_directionality': road['directionality'],
                'legal_highway_authority_verified': road['legal_highway_authority_verified']}
    if name == 'rel.oncoming':
        return {'other_vehicle_id': row['other_vehicle_id'],
                'route_direction': row['other_vehicle_route_direction']}
    raise ValueError('Unknown exact source channel: ' + name)


def finalize(attempt, output):
    attempt, output = Path(attempt), Path(output)
    if output.exists() or (attempt / 'result.json').exists():
        raise ValueError('Retain prior analysis; use a fresh attempt')
    for name in (*SOURCES, *VIDEOS, 'config.json', 'construction.json'):
        if not (attempt / name).is_file():
            raise ValueError('Missing required source: ' + name)
    config = json.loads((attempt / 'config.json').read_text())
    construction = json.loads((attempt / 'construction.json').read_text())
    case = config['case_id']
    if case != construction['case_id'] or config.get('supported_case_ids') != [case]:
        raise ValueError('Exact selected case differs')
    road = json.loads((attempt / 'road-context.json').read_text())
    metric = measure_feature(attempt / 'native-feature-source.jsonl', attempt / 'road-context.json')
    rows = read_rows(attempt / 'native-feature-source.jsonl')
    frame_map = read_rows(attempt / 'video_frames.jsonl')
    trace = read_rows(attempt / 'trace.jsonl')
    if len(frame_map) != 600 or len(trace) != 600:
        raise ValueError('Original trace/video frame count differs')
    for index, (row, mapping, pose) in enumerate(zip(rows, frame_map, trace)):
        if (mapping.get('video_frame') != index or mapping.get('native_frame') != row['native_frame'] or
                abs(mapping.get('time_s', -1) - row['time_s']) > 1e-6 or
                pose.get('frame') != mapping.get('carla_frame', mapping['native_frame'])):
            raise ValueError('Original Native/video/trace time join differs')
    expected = [c['name'] for c in construction['recording_description']['channels']]
    if expected != list(CHANNELS):
        raise ValueError('Selected measurement channels differ')
    channel_dir = attempt / 'channels'
    channel_dir.mkdir()
    evidence = []
    for channel in construction['recording_description']['channels']:
        name = channel['name']
        path = channel_dir / (name + '.jsonl')
        with path.open('x') as stream:
            for row, mapping in zip(rows, frame_map):
                stream.write(json.dumps({'time_s': mapping['time_s'],
                                         'value': value(name, row, road)},
                                        allow_nan=False) + '\n')
        evidence.append({'name': name, 'unit': channel['unit'],
                         'reference': 'channels/' + path.name})
    for source in construction['recording_description'].get('context_inputs', []):
        if source['name'] != 'road_geometry_source':
            raise ValueError('Unknown selected context input')
        evidence.append({'name': source['name'], 'unit': source['unit'],
                         'reference': 'road-context.json'})
    diagnostic = road.get('source_kind') == 'synthetic_cpu_diagnostic'
    source_hashes = {name: sha(attempt / name) for name in SOURCES}
    report = {'format': 'worker-analysis-report', 'case_id': case,
              'measurements': {'feature': {'method': 'measure_feature',
                  'value': metric, 'sources': source_hashes}},
              'source_complete': True, 'diagnostic_fixture': diagnostic,
              'physical_or_legal_acceptance': False}
    requested_left = any(p['target_lane_id'] != config['ego_lane_id'] for p in config['control_phases'])
    observed_left = metric['left_of_center_frame_count'] > 0
    result = {'case_id': case, 'measured_values': metric,
              'target_checks': [{'target': 'left-of-center body occupancy in the obstructed feature',
                'requested': requested_left, 'measured': observed_left,
                'method': 'measure_feature', 'tolerance': 0,
                'matched': requested_left == observed_left,
                'physical_cause_confirmed': False, 'cause_evidence': list(SOURCES)}],
              'setup_confirmed': False, 'behavior_attempted': not diagnostic,
              'maneuver_completed': False,
              'termination_reason': '600-frame CPU diagnostic' if diagnostic else '600-frame original Native attempt',
              'physical_failure_flags': ['Original roadway authority, visibility, pixels and legal interpretation pending'],
              'trace_reference': 'trace.jsonl', 'video_references': list(VIDEOS),
              'video_frame_map_reference': 'video_frames.jsonl',
              'recording_description': construction['recording_description'],
              'recording_evidence': evidence, 'realized_observables': {},
              'provenance_kind': 'synthetic_local_diagnostic' if diagnostic else 'original_native_attempt',
              'accepted': False}
    from worker_exchange.native_output import write_result
    write_result(attempt, result)
    output.write_text(json.dumps(report, indent=2, allow_nan=False) + '\n')
    return report


if __name__ == '__main__':
    p = argparse.ArgumentParser()
    p.add_argument('--attempt', required=True)
    p.add_argument('--output', required=True)
    args = p.parse_args()
    finalize(args.attempt, args.output)

"""Measure complete original source joins for the crest, curve and one-way cases.

The output is geometry and visibility evidence for review, not a statutory verdict.
"""
import hashlib
import json
from pathlib import Path

CAMERAS = ('overview', 'approach', 'reference_corner', 'driver_reference')
FRAMES = 600


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def read_rows(path):
    return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]


def measure(trace_path, road_path):
    road = json.loads(Path(road_path).read_text())
    rows = read_rows(trace_path)
    if len(rows) != FRAMES or [r.get('frame') for r in rows] != list(range(FRAMES)):
        raise ValueError('missing or disordered complete source trace')
    kind = road.get('feature_kind')
    if kind not in ('crest', 'curve') or road.get('feature_start_s_m') is None or road.get('feature_end_s_m') is None:
        raise ValueError('missing source feature geometry')
    start, end = float(road['feature_start_s_m']), float(road['feature_end_s_m'])
    if not 0 <= start < end or not road.get('road_geometry_sha256'):
        raise ValueError('invalid source feature interval or map binding')
    if kind == 'crest' and road.get('grade_profile_source') is None:
        raise ValueError('missing source grade profile')
    if kind == 'curve' and road.get('curvature_source') is None:
        raise ValueError('missing source curve profile')
    directionality = road.get('directionality')
    if directionality not in ('one_way', 'two_way') or road.get('centerline_source') is None:
        raise ValueError('missing source road directionality or centerline')
    approach, inside, left, obscured, opposing, sight = [], [], [], [], [], []
    for index, row in enumerate(rows):
        required = ('ego_id', 'ego_s_m', 'ego_forward_mps', 'ego_body_min_signed_m',
                    'ego_body_max_signed_m', 'sight_clear_m', 'sight_censored',
                    'camera_frame_ids', 'map_waypoint_source')
        if any(row.get(key) is None for key in required):
            raise ValueError('missing original ego, body, sightline or map source')
        if set(row['camera_frame_ids']) != set(CAMERAS) or any(row['camera_frame_ids'][name] != index for name in CAMERAS):
            raise ValueError('four-camera/source frame misjoin')
        s = float(row['ego_s_m'])
        if float(row['ego_forward_mps']) > 0 and s < start:
            approach.append(index)
        if start <= s <= end:
            inside.append(index)
        if float(row['ego_body_min_signed_m']) < 0:
            left.append(index)
        if not row['sight_censored'] and float(row['sight_clear_m']) < float(row.get('available_forward_road_m', 1e9)):
            obscured.append(index)
        if row.get('other_vehicle_id') is not None:
            if row.get('other_vehicle_route_direction') not in ('opposing', 'same') or row.get('other_vehicle_s_m') is None:
                raise ValueError('missing other participant route source')
            if row['other_vehicle_route_direction'] == 'opposing':
                opposing.append(index)
        sight.append(float(row['sight_clear_m']))
    if directionality == 'one_way' and opposing:
        raise ValueError('one-way source contradicts opposing participant route')
    active = set(approach if kind == 'crest' else inside)
    overlap = sorted(active & set(left) & set(obscured))
    return {'format': 'worker-feature-source-measurement-v1',
            'trace_sha256': sha(trace_path), 'road_sha256': sha(road_path),
            'frames': FRAMES, 'rate_hz': 20, 'feature_kind': kind,
            'feature_start_s_m': start, 'feature_end_s_m': end,
            'road_directionality': directionality,
            'one_way_exception_context': directionality == 'one_way',
            'approach_frame_count': len(approach), 'feature_frame_count': len(inside),
            'left_of_center_frame_count': len(left), 'obscured_frame_count': len(obscured),
            'active_left_obscured_first_frame': overlap[0] if overlap else None,
            'active_left_obscured_frame_count': len(overlap),
            'sight_clear_min_m': min(sight), 'sight_clear_max_m': max(sight),
            'opposing_vehicle_observed_frames': len(opposing),
            'hazard_distance_legal_judgment': None,
            'physical_completion': None}
